// Simulated Message Queue Workflow

const Queue = [];

// 1. PRODUCER (The Express API)
function handleUserUpload() {
  console.log("[API]: User uploaded a 4K Video.");
  // Put it in the queue instead of processing it right now!
  Queue.push({ task: "compress_video", videoId: 99 });
  console.log("[API]: Sent 200 OK to User instantly.\n");
}

// 2. CONSUMER (The Background Worker process)
function startBackgroundWorker() {
  setInterval(() => {
    if (Queue.length > 0) {
      const job = Queue.shift(); // Take the sticky note
      console.log(`[Worker]: Heavy CPU processing for ${job.task} ${job.videoId}...`);
    }
  }, 2000);
}

startBackgroundWorker();
handleUserUpload();
